// Client-side auth for React (SPA or pages) on top of Lila's session cookie.
//
//   <AuthProvider>               loads GET /api/auth/me (generated by `lila auth`)
//   const { user, login, logout, hasRole } = useAuth();
//   <RequireAuth roles={["admin"]}>...</RequireAuth>   or as a layout route (<Outlet />)
//   <GuestOnly>...</GuestOnly>                       login/register screens
//
// The server is still the security boundary: protect APIs with auth=True,
// roles=[...] or login_required; these guards only decide what to render.
import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { Navigate, Outlet, useInRouterContext, useLocation } from "react-router";
import { http, visit } from "./index";

export interface AuthUser {
  id: number | string;
  email?: string;
  name?: string;
  roles?: string[];
  role?: string;
  [key: string]: unknown;
}

export interface AuthEndpoints {
  me: string;
  login: string;
  register: string;
  logout: string;
}

export interface AuthContextValue {
  user: AuthUser | null;
  loading: boolean;
  authenticated: boolean;
  registerEnabled: boolean;
  login: (credentials: Record<string, unknown>) => Promise<AuthUser | null>;
  register: (data: Record<string, unknown>) => Promise<AuthUser | null>;
  logout: () => Promise<void>;
  refresh: () => Promise<AuthUser | null>;
  setUser: (user: AuthUser | null) => void;
  hasRole: (roles?: string | string[]) => boolean;
}

const DEFAULT_ENDPOINTS: AuthEndpoints = { me: "/api/auth/me", login: "/login", register: "/register", logout: "/logout" };
const AuthContext = createContext<AuthContextValue | null>(null);

/** True when the user has one of `roles` (no roles = any signed-in user). */
export function matchUserRole(user: AuthUser | null, roles?: string | string[]): boolean {
  if (!user) return false;
  const wanted = roles === undefined ? [] : Array.isArray(roles) ? roles : [roles];
  if (!wanted.length) return true;
  const owned = new Set([...(user.roles || []), ...(user.role ? [user.role] : [])]);
  return owned.has("*") || wanted.some((role) => owned.has(role));
}

export function AuthProvider({ endpoints, initialUser, children }: { endpoints?: Partial<AuthEndpoints>; initialUser?: AuthUser | null; children: ReactNode }) {
  const urls = useMemo(() => ({ ...DEFAULT_ENDPOINTS, ...endpoints }), [endpoints]);
  const [user, setUser] = useState<AuthUser | null>(initialUser ?? null);
  const [loading, setLoading] = useState(initialUser === undefined);
  const [registerEnabled, setRegisterEnabled] = useState(true);

  const refresh = useCallback(async () => {
    try {
      const data: any = await http(urls.me);
      const next = (data && data.user) || null;
      setUser(next);
      if (data && typeof data.register_enabled === "boolean") setRegisterEnabled(data.register_enabled);
      return next;
    } catch {
      setUser(null);
      return null;
    } finally {
      setLoading(false);
    }
  }, [urls.me]);

  useEffect(() => {
    if (initialUser === undefined) refresh();
  }, [initialUser, refresh]);

  const login = useCallback(async (credentials: Record<string, unknown>) => {
    await http(urls.login, { method: "POST", body: credentials });
    return refresh();
  }, [urls.login, refresh]);

  const register = useCallback(async (data: Record<string, unknown>) => {
    await http(urls.register, { method: "POST", body: data });
    return refresh();
  }, [urls.register, refresh]);

  const logout = useCallback(async () => {
    try {
      await http(urls.logout, { method: "POST", body: {} });
    } finally {
      setUser(null);
    }
  }, [urls.logout]);

  const value = useMemo<AuthContextValue>(() => ({
    user, loading, authenticated: Boolean(user), registerEnabled, login, register, logout, refresh, setUser,
    hasRole: (roles) => matchUserRole(user, roles),
  }), [user, loading, registerEnabled, login, register, logout, refresh]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const value = useContext(AuthContext);
  if (!value) throw new Error("useAuth() must be used inside <AuthProvider>");
  return value;
}

/** Router-aware redirect: <Navigate> inside React Router, otherwise a Lila visit. */
function Redirect({ to, page, from }: { to: string; page?: boolean; from?: string }) {
  const inRouter = useInRouterContext();
  useEffect(() => {
    if (page || !inRouter) {
      const target = from && to.startsWith("/login") ? `${to}${to.includes("?") ? "&" : "?"}next=${encodeURIComponent(from)}` : to;
      if (page) window.location.assign(target);
      else visit(target, { replace: true });
    }
  }, [to, page, from, inRouter]);
  if (!page && inRouter) return <RouterRedirect to={to} />;
  return null;
}

function RouterRedirect({ to }: { to: string }) {
  const location = useLocation();
  return <Navigate to={to} replace state={{ from: location }} />;
}

function Content({ children }: { children?: ReactNode }) {
  const inRouter = useInRouterContext();
  if (children !== undefined) return <>{children}</>;
  return inRouter ? <Outlet /> : null;
}

export interface RequireAuthProps {
  roles?: string | string[];
  /** Where guests go. A router path ("/login" inside the SPA) or, with `page`, a server page. */
  redirectTo?: string;
  /** Full page navigation (e.g. Lila's server-rendered /login, outside the SPA basename). */
  page?: boolean;
  /** Shown while /api/auth/me loads. */
  fallback?: ReactNode;
  /** Shown when the user lacks the role (default: an "Access denied" card). */
  forbidden?: ReactNode;
  children?: ReactNode;
}

export function RequireAuth({ roles, redirectTo = "/login", page = false, fallback = null, forbidden, children }: RequireAuthProps) {
  const { user, loading } = useAuth();
  if (loading) return <>{fallback}</>;
  if (!user) return <Redirect to={redirectTo} page={page} from={window.location.pathname + window.location.search} />;
  if (!matchUserRole(user, roles)) {
    return <>{forbidden ?? (
      <div role="alert" className="card mx-auto my-16 max-w-md p-8 text-center">
        <h2 className="card-title">403</h2>
        <p className="card-description">Access denied</p>
      </div>
    )}</>;
  }
  return <Content>{children}</Content>;
}

export function GuestOnly({ redirectTo = "/", page = false, fallback = null, children }: { redirectTo?: string; page?: boolean; fallback?: ReactNode; children?: ReactNode }) {
  const { user, loading } = useAuth();
  const inRouter = useInRouterContext();
  if (loading) return <>{fallback}</>;
  if (user) return inRouter && !page ? <GuestRedirect fallbackTo={redirectTo} /> : <Redirect to={redirectTo} page={page} />;
  return <Content>{children}</Content>;
}

function GuestRedirect({ fallbackTo }: { fallbackTo: string }) {
  const location = useLocation() as { state?: { from?: { pathname?: string } } };
  return <Navigate to={location.state?.from?.pathname || fallbackTo} replace />;
}
